<?php require_once __DIR__.'/../config/config.php'; require_admin(); $pdo=db(); if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)$_POST['id'];$status=$_POST['status'];$pdo->prepare('UPDATE messages SET status=? WHERE id=?')->execute([$status,$id]);flash('ok','Mensagem atualizada.');redirect('messages.php');}$rows=$pdo->query('SELECT * FROM messages ORDER BY id DESC')->fetchAll();require __DIR__.'/includes/header.php';?><div class="content"><h1>Mensagens</h1><div class="panel" style="margin-top:20px"><table class="table"><tr><th>Data</th><th>Cliente</th><th>Assunto</th><th>Status</th><th>Mensagem</th><th></th></tr><?php foreach($rows as $m):?><tr><td><?=e($m['created_at'])?></td><td><?=e($m['name'])?><br><?=e($m['email'])?></td><td><?=e($m['subject'])?></td><td><?=e($m['status'])?></td><td><?=e(mb_strimwidth($m['message'],0,80,'...'))?></td><td><form method="post" class="actions"><?=csrf_field()?><input type="hidden" name="id" value="<?=$m['id']?>"><select name="status"><option>new</option><option>read</option><option>replied</option><option>archived</option></select><button class="btn">Salvar</button></form></td></tr><?php endforeach;?></table></div></div><?php require __DIR__.'/includes/footer.php';
